const dictionary = new Map<string, string>();
const keyOf = (text: string) => text.replace(/_/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
for (const [key, english] of Object.entries(DICT.en)) {
  const translated = (DICT.kn as Record<string, string>)[key];
  if (translated) dictionary.set(keyOf(english), translated);
}
for (const [english, kannada] of Object.entries(extra)) dictionary.set(keyOf(english), kannada);
for (const [english, kannada] of Object.entries(kannadaLabels)) dictionary.set(keyOf(english), kannada);

export function kannadaUi(text: string): string {
  const exact = dictionary.get(keyOf(text));
  if (exact) return text.replace(text.trim(), exact);
  const name = kannadaName(text);
  if (name) return text.replace(text.trim(), name);
  const titleParts = text.trim().split(/\s+[-–—]\s+/);
  if (titleParts.length > 1 && titleParts.every(part => dictionary.has(keyOf(part)))) {
    return titleParts.map(part => dictionary.get(keyOf(part))).join(' — ');
  }
  if (/^[A-Za-z_]+\.[A-Za-z_]+$/.test(text.trim())) {
    return text.trim().split('.').map(part => dictionary.get(keyOf(part)) || part).join(' · ');
  }
  const punctuated = text.match(/^(\s*)(.+?)([ ·:,()]+)$/);
  if (punctuated) {
    const translated = dictionary.get(keyOf(punctuated[2]));
    if (translated) return punctuated[1] + translated + punctuated[3];
  }
  const patterns: Array<[RegExp, (...values: string[]) => string]> = [
    [/^(\d+) critical priority$/i, n => `${n} ಅತ್ಯಂತ ಗಂಭೀರ ಆದ್ಯತೆಯ ಪ್ರಕರಣಗಳು`],
    [/^of (\d+) FIRs on record$/i, n => `ದಾಖಲಾದ ${n} ಎಫ್‌ಐಆರ್‌ಗಳಲ್ಲಿ`],
    [/^(\d+(?:\.\d+)?)% case solve rate$/i, n => `${n}% ಪ್ರಕರಣ ಪರಿಹಾರ ಪ್ರಮಾಣ`],
    [/^(\d+) geolocated FIRs · from Cloud Scale$/i, n => `ಸ್ಥಳ ಗುರುತಿಸಿದ ${n} ಎಫ್‌ಐಆರ್‌ಗಳು · Cloud Scale ನಿಂದ`],
    [/^(.+) leads with (\d+) FIRs\.$/, (district, n) => `${district}: ${n} ಎಫ್‌ಐಆರ್‌ಗಳೊಂದಿಗೆ ಮುಂಚೂಣಿಯಲ್ಲಿದೆ.`],
    [/^(.+) leads with (\d+) FIRs on record\.$/, (offence, n) => `${kannadaUi(offence)} ${n} ಎಫ್‌ಐಆರ್‌ಗಳೊಂದಿಗೆ ಮುಂಚೂಣಿಯಲ್ಲಿದೆ.`],
    [/^(.+) is the top hotspot \((\d+) FIRs\)\.$/, (district, n) => `${district} ಪ್ರಮುಖ ಅಪರಾಧ ಕೇಂದ್ರ (${n} ಎಫ್‌ಐಆರ್‌ಗಳು).`],
    [/^Incidents (up|down) ([\d.]+)% over the last 30 days\.$/, (direction, n) => `ಕಳೆದ 30 ದಿನಗಳಲ್ಲಿ ಘಟನೆಗಳ ಪ್ರಮಾಣ ${n}% ${direction === 'up' ? 'ಹೆಚ್ಚಾಗಿದೆ' : 'ಕಡಿಮೆಯಾಗಿದೆ'}.`],
    [/^(\d+) repeat offenders across the state\.$/, n => `ರಾಜ್ಯಾದ್ಯಂತ ${n} ಪುನರಾವರ್ತಿತ ಅಪರಾಧಿಗಳು.`],
    [/^(.+) is the most frequent \((\d+)\)\.$/, (offence, n) => `${kannadaUi(offence)} ಅತಿ ಹೆಚ್ಚು ದಾಖಲಾಗಿದೆ (${n}).`],
    [/^(\d+) cases currently require investigation follow-up\.$/, n => `${n} ಪ್ರಕರಣಗಳಿಗೆ ತನಿಖಾ ಮುಂದುವರಿಕೆ ಅಗತ್ಯವಿದೆ.`],
    [/^(\d+) arrests were recorded in the latest 30-day window\.$/, n => `ಕಳೆದ 30 ದಿನಗಳಲ್ಲಿ ${n} ಬಂಧನಗಳು ದಾಖಲಾಗಿವೆ.`],
    [/^(\d+) (records|links|rows|sources|cases|days|linked FIRs)$/i, (n, unit) => `${n} ${kannadaUi(unit)}`],
    [/^([\d,]+) records · ([\d,]+) loaded · (\d+) columns$/i, (n, loaded, columns) => `${n} ದಾಖಲೆಗಳು · ${loaded} ಲೋಡ್ ಆಗಿವೆ · ${columns} ಅಂಕಣಗಳು`],
    [/^(\d+)d ago$/, n => `${n} ದಿನಗಳ ಹಿಂದೆ`],
    [/^(\d+)(s|m|h|mo|y) ago$/, (n, unit) => `${n} ${{s: 'ಸೆಕೆಂಡುಗಳ', m: 'ನಿಮಿಷಗಳ', h: 'ಗಂಟೆಗಳ', mo: 'ತಿಂಗಳುಗಳ', y: 'ವರ್ಷಗಳ'}[unit]} ಹಿಂದೆ`],
  ];
  for (const [pattern, format] of patterns) {
    const match = text.trim().match(pattern);
    if (match) return format(...match.slice(1));
  }
  return text;
}

export function interfaceText(lang: string, text: string): string {
  return lang === 'kn' ? kannadaUi(text) : text;
}

export function matchesUiText(values: unknown[], query: string): boolean {
  const needle = query.trim().toLocaleLowerCase();
  return values.some(value => {
    const raw = String(value ?? '');
    return raw.toLocaleLowerCase().includes(needle) || kannadaUi(raw).toLocaleLowerCase().includes(needle);
  });
}
